#!/usr/bin/env node
// Validates the asset sources in src/assets and generates the typed registries in
// src/assets/generated. With --check, it verifies that the generated files match a fresh run
// instead of writing them. Nothing here is listed by hand. Run with `yarn assets`.
import { Buffer } from 'node:buffer';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const SOURCE_FOLDERS = {
  icons: '.svg',
  images: '.png',
};
// Folders that `yarn assets` leaves alone: fonts are linked natively, Lottie files are imported,
// icons-source feeds `yarn icons` (the native app icons), and generated is written by this script.
const OTHER_FOLDERS = ['fonts', 'animations', 'icons-source', 'generated'];
const KEBAB_CASE = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;
const DENSITY_SUFFIX = /@([23])x$/;
const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
// react-native-svg renders none of these.
const UNSUPPORTED_SVG =
  /<(style|script|foreignObject|filter|fe[A-Z]\w*|animate\w*|set|switch)[\s/>]/g;
const COLOR_FUNCTION = String.raw`(?:rgba?|hsla?|url)\([^)]*\)`;
const COLOR_ATTRIBUTE = new RegExp(
  String.raw`\b(?:fill|stroke|stop-color|color)\s*[=:]\s*["']?(?<value>${COLOR_FUNCTION}|[^"';\s]+)`,
  'g',
);
const NO_COLOR = new Set(['none', 'currentcolor', 'transparent', 'inherit']);
const HEADER = 'Generated by `yarn assets` from src/assets. Do not edit.';

const require = createRequire(import.meta.url);
const { default: PRETTIER_CONFIG } = await import('../prettier.config.mjs');

function toPosix(path) {
  return path.split(sep).join('/');
}

function listFiles(dir) {
  return existsSync(dir)
    ? readdirSync(dir, { recursive: true })
        .map(toPosix)
        .filter((file) => statSync(join(dir, file)).isFile())
        .sort()
    : [];
}

function pngSize(buffer) {
  return buffer.length < 24 || !buffer.subarray(0, 8).equals(PNG_SIGNATURE)
    ? null
    : { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

function normalizeColor(value) {
  const color = value.toLowerCase();
  const short = /^#([0-9a-f])([0-9a-f])([0-9a-f])$/.exec(color);
  return short ? `#${short[1]}${short[1]}${short[2]}${short[2]}${short[3]}${short[3]}` : color;
}

/** The distinct paint colors of an SVG, ignoring `none` and `currentColor`. */
export function svgColors(svg) {
  const colors = [...svg.matchAll(COLOR_ATTRIBUTE)]
    .map((match) => normalizeColor(match.groups.value))
    .filter((color) => !NO_COLOR.has(color) && !color.startsWith('url('));
  return [...new Set(colors)];
}

/** Why `file` cannot be a source of `folder`, or an empty string. */
function fileProblem(folder, extension, file) {
  if (file.includes('/') || !file.endsWith(extension)) {
    return `${folder}/ holds flat ${extension} files only`;
  }
  const hasDensity = DENSITY_SUFFIX.test(file.slice(0, -extension.length));
  return folder !== 'images' && hasDensity ? 'only images/ has density variants' : '';
}

/** Loose files and unknown folders directly in `src/assets`. */
function topLevelProblems(assetsDir) {
  const problems = [];
  for (const entry of existsSync(assetsDir) ? readdirSync(assetsDir).sort() : []) {
    if (!statSync(join(assetsDir, entry)).isDirectory()) {
      if (entry !== 'README.md') {
        problems.push(`${entry}: put assets in icons/ or images/`);
      }
    } else if (!(entry in SOURCE_FOLDERS) && !OTHER_FOLDERS.includes(entry)) {
      problems.push(`${entry}/: unknown asset folder`);
    }
  }
  return problems;
}

/** The asset sources, grouped by registry: icons and images (by density). */
export function readAssetSources(assetsDir) {
  const sources = { icons: [], images: [] };
  const problems = topLevelProblems(assetsDir);

  for (const [folder, extension] of Object.entries(SOURCE_FOLDERS)) {
    for (const file of listFiles(join(assetsDir, folder))) {
      const path = `${folder}/${file}`;
      const problem = fileProblem(folder, extension, file);
      if (problem) {
        problems.push(`${path}: ${problem}`);
        continue;
      }
      const stem = file.slice(0, -extension.length);
      sources[folder].push({
        folder,
        name: stem.replace(DENSITY_SUFFIX, ''),
        density: Number(DENSITY_SUFFIX.exec(stem)?.[1] ?? 1),
        path,
        content: readFileSync(join(assetsDir, path)),
      });
    }
  }
  return { sources, problems };
}

function nameProblems(sources) {
  const all = [...sources.icons, ...sources.images];
  const problems = all
    .filter((asset) => !KEBAB_CASE.test(asset.name))
    .map((asset) => `${asset.path}: names are kebab-case (for example cart-empty)`);

  const foldersByName = new Map();
  for (const asset of all) {
    foldersByName.set(
      asset.name,
      new Set([...(foldersByName.get(asset.name) ?? []), asset.folder]),
    );
  }
  for (const [name, folders] of foldersByName) {
    if (folders.size > 1) {
      problems.push(`${name}: the name is used in ${[...folders].sort().join(' and ')}`);
    }
  }
  return problems;
}

function duplicateContentProblems(sources) {
  const pathsByHash = new Map();
  for (const asset of [...sources.icons, ...sources.images]) {
    const hash = createHash('sha256').update(asset.content).digest('hex');
    pathsByHash.set(hash, [...(pathsByHash.get(hash) ?? []), asset.path]);
  }
  return [...pathsByHash.values()]
    .filter((paths) => paths.length > 1)
    .map((paths) => `${paths.join(', ')}: the same file more than once`);
}

function svgProblems(asset) {
  const svg = asset.content.toString('utf8');
  const problems = [];
  if (!/<svg[\s>]/.test(svg)) {
    return [`${asset.path}: not an SVG file`];
  }
  if (!/<svg[^>]*\sviewBox=/.test(svg)) {
    problems.push(`${asset.path}: add a viewBox, so the asset scales`);
  }
  const unsupported = [...new Set([...svg.matchAll(UNSUPPORTED_SVG)].map((match) => match[1]))];
  if (unsupported.length > 0) {
    problems.push(`${asset.path}: react-native-svg does not render <${unsupported.join('>, <')}>`);
  }
  const colors = svgColors(svg);
  if (colors.length > 1 || /<(?:linear|radial)Gradient[\s>]/.test(svg)) {
    problems.push(`${asset.path}: icons have one color, so the color prop can tint them`);
  }
  return problems;
}

function imageProblems(images) {
  const problems = [];
  const byName = new Map();
  for (const image of images) {
    const size = pngSize(image.content);
    if (!size) {
      problems.push(`${image.path}: not a PNG file`);
      continue;
    }
    byName.set(image.name, [...(byName.get(image.name) ?? []), { ...image, ...size }]);
  }
  for (const [name, variants] of byName) {
    const base = variants.find((variant) => variant.density === 1);
    const missing = [1, 2, 3].filter((density) => !variants.some((v) => v.density === density));
    if (missing.length > 0) {
      const files = missing.map((density) =>
        density === 1 ? `${name}.png` : `${name}@${density}x.png`,
      );
      problems.push(`images/${name}: add ${files.join(' and ')} (every image has 1x, 2x and 3x)`);
    }
    for (const variant of base ? variants.filter((v) => v.density !== 1) : []) {
      const expected = {
        width: base.width * variant.density,
        height: base.height * variant.density,
      };
      if (variant.width !== expected.width || variant.height !== expected.height) {
        problems.push(
          `${variant.path}: is ${variant.width}x${variant.height}, expected ${expected.width}x${expected.height} (${variant.density} times ${name}.png)`,
        );
      }
    }
  }
  return problems;
}

/** Every problem with the asset sources; an empty list means `yarn assets` may generate. */
export function findAssetProblems(assetsDir) {
  const { sources, problems } = readAssetSources(assetsDir);
  return [
    ...problems,
    ...nameProblems(sources),
    ...duplicateContentProblems(sources),
    ...sources.icons.flatMap(svgProblems),
    ...imageProblems(sources.images),
  ];
}

/** An object key the way Prettier prints it: bare when it is a valid identifier. */
function propertyKey(name) {
  return /^[a-z][a-z0-9]*$/.test(name) ? name : `'${name}'`;
}

function componentName(name) {
  return name.replaceAll(/(?:^|-)([a-z0-9])/g, (_, letter) => letter.toUpperCase());
}

/** Single-color icons are drawn in `currentColor`, which the Icon component sets from its color prop. */
function tintable(svg) {
  const [color] = svgColors(svg);
  return color
    ? svg.replaceAll(COLOR_ATTRIBUTE, (match, ...args) => {
        const { value } = args.at(-1);
        return normalizeColor(value) === color ? match.replace(value, 'currentColor') : match;
      })
    : svg;
}

function runSvgr(inputDir, outDir) {
  const svgoConfig = {
    // Keep the viewBox (sizes come from props) and drop xmlns, which react-native-svg's types reject.
    plugins: [
      { name: 'preset-default', params: { overrides: { removeViewBox: false } } },
      'removeXMLNS',
    ],
  };
  const result = spawnSync(
    process.execPath,
    [
      require.resolve('@svgr/cli/bin/svgr'),
      '--native',
      '--typescript',
      '--jsx-runtime',
      'automatic',
      '--no-dimensions',
      '--no-index',
      '--filename-case',
      'pascal',
      '--ext',
      'tsx',
      '--svgo-config',
      JSON.stringify(svgoConfig),
      // The project's Prettier style, without config lookups, so every run prints the same code.
      '--no-runtime-config',
      '--prettier-config',
      JSON.stringify(PRETTIER_CONFIG),
      '--silent',
      '--out-dir',
      outDir,
      inputDir,
    ],
    { encoding: 'utf8' },
  );
  if (result.status !== 0) {
    throw new Error(`svgr failed:\n${result.stderr || result.stdout}`);
  }
}

function writeSvgRegistry(outDir, registry, assets, transform) {
  const tempDir = mkdtempSync(join(tmpdir(), `assets-${registry}-`));
  try {
    for (const asset of assets) {
      writeFileSync(join(tempDir, `${asset.name}.svg`), transform(asset.content.toString('utf8')));
    }
    runSvgr(tempDir, join(outDir, registry));
    for (const file of readdirSync(join(outDir, registry))) {
      const path = join(outDir, registry, file);
      writeFileSync(path, `// ${HEADER}\n${readFileSync(path, 'utf8')}`);
    }
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }

  const constant = registry.toUpperCase();
  const type = `${componentName(registry).replace(/s$/, '')}Name`;
  const imports = assets.map(
    (asset) =>
      `import ${componentName(asset.name)} from './${registry}/${componentName(asset.name)}';`,
  );
  const entries = assets.map(
    (asset) => `  ${propertyKey(asset.name)}: ${componentName(asset.name)},`,
  );
  writeFileSync(
    join(outDir, `${registry}.registry.ts`),
    `// ${HEADER}\n${imports.join('\n')}\n\nexport const ${constant} = {\n${entries.join('\n')}\n} as const;\n`,
  );
  writeTypes(
    outDir,
    registry,
    type,
    assets.map((asset) => asset.name),
  );
}

function writeTypes(outDir, registry, type, names) {
  const members = names.map((name) => `  | '${name}'`).join('\n');
  writeFileSync(
    join(outDir, `${registry}.types.ts`),
    `// ${HEADER}\nexport type ${type} =\n${members};\n`,
  );
}

function writeImageRegistry(outDir, images) {
  const names = [...new Set(images.map((image) => image.name))];
  const entries = names.map((name) => `  ${propertyKey(name)}: require('../images/${name}.png'),`);
  writeFileSync(
    join(outDir, 'images.registry.ts'),
    `// ${HEADER} Metro picks the @2x and @3x files.\nexport const IMAGES = {\n${entries.join('\n')}\n} as const;\n`,
  );
  writeTypes(outDir, 'images', 'ImageName', names);
}

/**
 * Writes the registries for the valid sources in `assetsDir` into `outDir`, which is replaced,
 * and returns how many assets each registry has. A registry with no assets is not written.
 */
export function generateAssets(assetsDir, outDir) {
  const problems = findAssetProblems(assetsDir);
  if (problems.length > 0) {
    throw new Error(`Fix the asset sources first:\n${problems.join('\n')}`);
  }
  const { sources } = readAssetSources(assetsDir);
  const counts = {
    icons: sources.icons.length,
    images: new Set(sources.images.map((image) => image.name)).size,
  };
  rmSync(outDir, { recursive: true, force: true });
  if (counts.icons + counts.images === 0) {
    return counts;
  }
  mkdirSync(outDir, { recursive: true });
  if (sources.icons.length > 0) {
    writeSvgRegistry(outDir, 'icons', sources.icons, tintable);
  }
  if (sources.images.length > 0) {
    writeImageRegistry(outDir, sources.images);
  }
  return counts;
}

/** Differences between the committed generated files and a fresh run. */
export function checkAssets(assetsDir, generatedDir) {
  const problems = findAssetProblems(assetsDir);
  if (problems.length > 0) {
    return problems;
  }
  const tempDir = mkdtempSync(join(tmpdir(), 'assets-check-'));
  const freshDir = join(tempDir, 'generated');
  try {
    generateAssets(assetsDir, freshDir);
    const fresh = listFiles(freshDir);
    const committed = listFiles(generatedDir);
    return [
      ...fresh
        .filter((file) => !committed.includes(file))
        .map((file) => `generated/${file} is missing`),
      ...committed
        .filter((file) => !fresh.includes(file))
        .map((file) => `generated/${file} is stale`),
      ...fresh
        .filter((file) => committed.includes(file))
        .filter(
          (file) =>
            !readFileSync(join(freshDir, file)).equals(readFileSync(join(generatedDir, file))),
        )
        .map((file) => `generated/${file} is out of date`),
    ];
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
}

function main() {
  const rootDir = join(dirname(fileURLToPath(import.meta.url)), '..');
  const assetsDir = join(rootDir, 'src/assets');
  const generatedDir = join(assetsDir, 'generated');

  if (process.argv.includes('--check')) {
    const problems = checkAssets(assetsDir, generatedDir);
    if (problems.length > 0) {
      console.error(`Assets are not up to date. Run yarn assets.\n${problems.join('\n')}`);
      process.exit(1);
    }
    console.log('Assets are valid and the generated files are current.');
    return;
  }

  const problems = findAssetProblems(assetsDir);
  if (problems.length > 0) {
    console.error(problems.join('\n'));
    process.exit(1);
  }
  const counts = generateAssets(assetsDir, generatedDir);
  console.log(
    `${relative(rootDir, generatedDir)}: ${counts.icons} icons, ${counts.images} images.`,
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main();
}
